sec.top_margin=Inches(.7); sec.bottom_margin=Inches(.7); sec.left_margin=Inches(.8); sec.right_margin=Inches(.8)
for n,s,c in [('Title',26,'17365D'),('Heading 1',19,'17365D'),('Heading 2',14,'1F4E79'),('Heading 3',11,'2F5597')]:
 st=d.styles[n]; st.font.name='Aptos Display'; st.font.size=Pt(s); st.font.bold=True; st.font.color.rgb=RGBColor.from_string(c)
d.styles['Normal'].font.name='Aptos'; d.styles['Normal'].font.size=Pt(10)
def para(x='',style=None): return d.add_paragraph(x,style)
def h(x,l=1): d.add_heading(x,l)
def bullets(xs):
 for x in xs:d.add_paragraph(x,'List Bullet')
def nums(xs):
 for x in xs:d.add_paragraph(x,'List Number')
def table(head,rows):
 t=d.add_table(rows=1,cols=len(head));t.style='Light Shading Accent 1';t.alignment=WD_TABLE_ALIGNMENT.CENTER
 for i,x in enumerate(head):
  c=t.rows[0].cells[i];c.text=x;sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'17365D');c._tc.get_or_add_tcPr().append(sh)
  for r in c.paragraphs[0].runs:r.font.bold=True;r.font.color.rgb=RGBColor(255,255,255)
 for row in rows:
  for c,x in zip(t.add_row().cells,row):c.text=x
 d.add_paragraph()

p=d.add_paragraph(style='Title');p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run('Casino Project Code Walkthrough Workbook')
p=d.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;r=p.add_run('A practical learning path from screen click to database row');r.italic=True;r.font.size=Pt(12)
para('Use this workbook together with Casino_DBMS_End_to_End_Study_Guide.docx. The earlier guide teaches the DBMS ideas; this companion teaches how those ideas appear in this repository. The goal is to trace a feature without guessing: start at the screen, follow the HTTP call, inspect guards and controller logic, then locate the SQL or Mongo operation and explain the returned result.')
h('A repeatable method for understanding any feature')
nums(['Find the visible page under frontend/app and identify the event handler triggered by a button or page load.','Find the function called by the page in frontend/lib/api.js, or note that the page uses the shared Axios instance directly. Record HTTP method, path, request body, and query parameters.','Find the matching backend route. Read middleware from left to right: authentication, authorization, validation, controller.','Open the controller. Record where each value comes from: req.body, req.params, req.query, or req.user. Trace every database helper call.','Open the SQL procedure/query or Mongo model method. Identify tables/collections, predicates, writes, transaction boundary, and side effects.','Follow the response mapping back to the page. Check whether the UI reads the response shape the controller actually returns.','State the intended behavior, then check whether the actual code achieves it. List mismatches rather than silently assuming they work.'])
h('Application map')
table(['Area','Role in the application','Start reading here'],[
('Frontend pages','Render user experience and collect inputs','frontend/app/'),('Shared frontend state','Keeps user/token in React and localStorage','frontend/components/AuthProvider.js'),('API client','Base URL, bearer token, endpoint helpers','frontend/lib/api.js'),('Express startup','Middleware and route mounting; DB connection startup','backend/src/server.js'),('Routes','URL/method and access guard composition','backend/src/routes/'),('Controllers','Business flow and response shape','backend/src/controllers/'),('MySQL helper','mysql2 pool, query, procedure call','backend/src/config/database.js'),('MySQL definitions','Tables, business routines, triggers, data, reports','database/mysql/'),('Mongo side','Models, connection, analytics, vector functions','backend/src/config/mongodb.js; database/nosql/')])

h('Journey 1 Registration and login')
h('Follow the registration request',2)
nums(['Open frontend/app/register/page.js. The form collects name, email, phone, dateOfBirth, password, confirmPassword. Browser checks required values, matching passwords, a six-character minimum, and age.','The form calls register from useAuth in frontend/components/AuthProvider.js. That calls authAPI.register in frontend/lib/api.js, a POST to /auth/register.','backend/src/routes/index.js mounts authRoutes at /api/auth. authRoutes.js sends POST /register straight to authController.register. Notice the route does not attach registerValidation even though that validator exists.','authController.register checks email and phone duplicates, bcrypt-hashes the password at cost 10, inserts PLAYER with parameter placeholders, looks up the new ID and role summary, signs JWT, reads the wallet, and returns response JSON.','The PLAYER INSERT triggers in database/mysql/triggers.sql create a wallet and default PLAYER assignment. These depend on the triggers having been installed.','AuthProvider extracts response.data.data, stores token and player in localStorage, updates React context, and the page navigates to dashboard.'])
h('What to explain',2)
para('The browser is a client and cannot be trusted to enforce rules. Server-side express-validator chains are defined in backend/src/middleware/validator.js but are not wired into authRoutes.js for register/login. Unique indexes still protect email/phone from duplicates at database level, but concurrent duplicates may produce an unhandled database error. bcrypt stores a one-way password hash; the database never needs the original password. JWT is a signed bearer credential, not encrypted storage.')
h('Journey 2 Authenticated API request')
nums(['AuthProvider hydrates state from localStorage on page load.','frontend/lib/api.js request interceptor reads token and adds Authorization: Bearer <token>.','authenticate in backend/src/middleware/auth.js checks header shape, verifies JWT using JWT_SECRET, then queries MySQL for current player status and active roles.','Middleware builds req.user with playerId, roles, isAdmin/isDealer, etc. The route guard or controller uses this context.','If token is invalid/expired, middleware returns 401; Axios response interceptor clears local state and redirects to /login.'])
para('Security discussion: JWT payload includes identity and role claims, but middleware refreshes roles from the database. Logout only clears browser storage; no token revocation list exists. Role checks in React hide pages but do not secure APIs; server middleware is the actual guard.')
h('Journey 3 Wallet operation')
table(['Layer','What happens','Inspect'],[
('Page','Loads wallet+transactions in parallel; validates positive amount in browser; posts deposit or withdrawal and refreshes.','frontend/app/wallet/page.js'),('API','Uses shared Axios token; endpoint is /wallet/deposit or /wallet/withdraw.','frontend/lib/api.js'),('Route','All wallet routes require authenticate and PLAYER role; transaction amounts are validated.','backend/src/routes/walletRoutes.js; middleware/validator.js'),('Controller','Reads WALLET by authenticated player ID; writes by calling stored procedure; history filters by wallet ID.','backend/src/controllers/walletController.js'),('Procedure','Locks wallet row, captures before balance, validates positive amount and funds, updates balance, inserts transaction record, commits.','database/mysql/procedures.sql'),('Trigger','Observes WALLET balance update and creates a generic transaction record too.','database/mysql/triggers.sql')])
para('Trace the intended deposit: +amount changes balance, and one DEPOSIT transaction should record before/after. Actual implementation inserts a transaction explicitly inside procedure and again through the update trigger. Withdrawals similarly duplicate records. Triggers classify update-generated transactions generically, so types/sign conventions can differ. This is why you should distinguish ledger intent from actual stored rows.')
h('Journey 4 Place a bet')
nums(['The game detail page frontend/app/games/[id]/page.js reads the game and wallet, then submits gameId, amount, betType.','betsAPI.place sends POST /bets. betRoutes applies authenticate, placeBetValidation, then betController.placeBet.','The controller never accepts playerId from the browser; it takes req.user.playerId, then calls place_bet with the four arguments.','The procedure starts a transaction, checks player/game active status, locks the wallet with SELECT FOR UPDATE, checks available balance, inserts PENDING BET, subtracts the amount, then commits.','BET triggers also check table min/max, player/game state, balance, and subtract wallet after insertion.','The controller translates result columns bet_id/new_balance into a 201 response; page refreshes the wallet.'])
para('Expected invariant: a single bet should reduce balance exactly once and create exactly one audit entry. Actual code reduces it once in place_bet and again in trigger_deduct_bet_from_wallet. The wallet update triggers create a transaction classified as WITHDRAWAL. Explain that the transaction is atomic at the SQL level but business logic is duplicated, so atomicity alone does not guarantee the right amount.')
h('Journey 5 Bet history and stats')
para('GET /bets/history and /bets/stats are authenticated. betController.getBetHistory filters BET by req.user.playerId, joins GAME and CASINO_TABLE, orders newest first, paginates, and separately counts rows. getPlayerStats calls get_player_statistics. The dashboard uses only the default result page to calculate its own cards; its supposed all-time stats may represent only the page loaded. The stored procedure counts distinct games and uses conditional aggregates for wins/losses.')
h('Journey 6 Settle a bet')
nums(['Dealer UI posts PUT /bets/:id/settle with outcome and payout.','Route requires authenticated DEALER or ADMIN and validates outcome/payout.','Controller calls settle_bet. Procedure locks the BET row and rejects already-settled rows.','Procedure updates BET; for WON and positive payout it adds payout to WALLET.','The AFTER UPDATE BET trigger sees PENDING -> WON and adds payout again, then creates an explicit PAYOUT record. Wallet update trigger may add another generic credit record.'])
para('Before a production-quality settlement, one layer must own crediting and ledger writes. Validate payout/outcome combinations, make settlement idempotent, and test every outcome including CANCELLED.')
h('Journey 7 Browse and create games')
para('Game list/detail reads are in gameController.js. They join GAME to CASINO_TABLE and DEALER and use parameterized ? placeholders. The routes require authentication. Dealer/Admin creation route calls createGame; however, gameController.js uses SELECT * FROM create_game($1, $2, $3), and endGame similarly calls end_game using PostgreSQL syntax. Neither procedure exists in database/mysql/procedures.sql. Thus the screen and route exist, but the MySQL-backed write path is incomplete. The trigger updates table occupancy when a game row is inserted/ended, but that does not repair the mismatched controller call.')
h('Journey 8 Table list and management')
para('tableController.js reads CASINO_TABLE and active GAME data. Some reads work with no optional filter, but filtered queries use $n placeholders incompatible with mysql2. Table detail also uses $1. Create/update use RETURNING and PostgreSQL error code handling. Routes require MANAGER, while database/mysql/rbac.sql only defines PLAYER, DEALER, ADMIN. So table write operations have both a dialect issue and a role mismatch.')
h('Journey 9 Admin and RBAC')
para('Admin UI calls GET /auth/players, PATCH /auth/players/:id/status, and POST /auth/assign-role. authRoutes guards each with authorize(ADMIN). The controller queries active user-role mappings and calls assign_role for assignment. rbac.sql creates ROLE, USER_ROLE, PERMISSION, ROLE_PERMISSION; seeds permission definitions and joins roles to permissions. `authorize` checks role names; `hasPermission` does a database permission lookup but is not used by these route declarations. Therefore permission tables exist, but most API enforcement is role-level. The admin UI’s status update changes PLAYER.status; authenticate subsequently blocks inactive users.')
h('Journey 10 Mongo event logging and analytics')
para('Mongo connects through backend/src/config/mongodb.js when server starts. Analytics routes call functions in analyticsController.js, which checks connection and returns 503 if unavailable. POST /analytics/game/:gameId/event appends an event in an upserted GameLog document and increments bet/payout aggregate fields based on event type. GET routes retrieve daily analytics/game logs/player activity. Admin refresh aggregates GameLog docs into CasinoAnalytics. MySQL bet controllers do not call the Mongo logging endpoint, so activity does not automatically synchronize between stores.')
h('Journey 11 Vector recommendation')
nums(['database/nosql/mongodb-setup.js seeds six game vectors and a player preference vector.','frontend/app/analytics/page.js fetches game vectors and player recommendations, then renders five sliders.','On submit, it sends a numeric five-element vector to POST /analytics/vectors/recommend.','analyticsRoutes checks array shape and calls searchVectorRecommendations.','analyticsController loads every game vector, computes cosine similarity in JS, sorts by score descending, and slices topK.','The UI displays the ranked results and score as a percentage-style match.'])
para('Dimensions encode risk, house edge, pace, skill, and social interaction. Scores compare direction in this manually designed space; they are not probabilities. This is a vector similarity demonstration stored in MongoDB, not a neural model or specialized indexed vector service.')
h('Database source tour')
table(['File','Purpose','Question to ask while reading'],[
('database/mysql/schema.sql','Core MySQL tables, keys, checks, indexes','Which invariant is structural and which is procedural?'),('database/mysql/rbac.sql','Role and permission relations, seeds, view, procedures','Which many-to-many relationships are represented?'),('database/mysql/procedures.sql','Bet, settlement, deposit, withdrawal, stats','Where does each transaction begin/commit/rollback?'),('database/mysql/triggers.sql','Automatic validation and side effects','Could another layer perform the same write?'),('database/mysql/seed.sql','Demo relational records','Are inserts compatible with installed triggers?'),('database/mysql/queries.sql','Reports and advanced SQL demonstrations','What is the row grain and why each join?'),('database/nosql/mongodb-schema.js','Mongoose document shapes and cosine helper','Which nested attributes need flexibility?'),('database/nosql/mongodb-setup.js','Mongo sample data creation','Which collections and vector shapes are created?'),('database/nosql/mongodb-queries.js','Read/update/delete and similarity demos','Which operations demonstrate RUD?')])
h('Learning labs')
h('Lab 1 Map an endpoint',2);para('Choose GET /wallet. Write the exact path from wallet page -> Axios -> walletRoutes -> authenticate -> authorize -> getWallet -> SELECT -> response. Identify where player identity comes from. Explain why the query is parameterized.')
h('Lab 2 Explain a procedure',2);para('Read place_bet. For every validation, name the data read, error raised, and state protected. Mark the lock, insert, debit, and commit. Then trace triggers and explain why the actual result violates the intended one-debit invariant.')
h('Lab 3 Explain a report query',2);para('Select the daily performance CTE in database/mysql/queries.sql. Write the grain of daily_stats, summary, and final output. Explain COUNT DISTINCT, COALESCE, CASE, NULLIF, and why it uses a LEFT JOIN.')
h('Lab 4 Explain a vector result',2);para('Take a target vector and one stored game vector. Calculate dot product and both magnitudes by hand, then divide. Explain how sorting and topK produce recommendations and why the output is not a probability.')
h('Lab 5 Inspect access control',2);para('For each route group, record authentication and role requirements. Compare to ROLE enum values. Find a route where permission records are not used and a route where the code requests MANAGER. Explain how you would make route and data roles consistent.')
h('Lab 6 Defend a limitation',2);para('Prepare a clear, non-defensive answer: “The intended design is X. The current path in files A/B does Y, because of Z. The user-visible effect is W. I would correct it by making one layer authoritative and adding an integration check.” Practice using duplicate bet debit or PostgreSQL table syntax.')
h('Final oral explanation template')
para('“When the user [action] on [page], the page calls [HTTP method/path] through [API helper]. The route applies [authentication/authorization/validation] and calls [controller]. The controller gets [identity/input] from [request source] and runs [SQL procedure/query or Mongo operation]. The database enforces [constraint/transaction/trigger]. The controller returns [response], and the page [state update]. In the current code, [limitation if relevant]. The DBMS concept demonstrated is [concept] because [reason].”')

